head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > loadGlobalCommon]<br/>전역(Global) 공통 JavaScript 모듈을 비동기로 로드하여 프로젝트 공통 변수에 등록합니다.<br/>",
    "validation" : [
        "전역(Global) 공통 JavaScript 모듈을 비동기로 로드하여 프로젝트 공통 변수($c)에 등록할 수 있어야 합니다.",
        "infoArray(필수) 파라미터로 로드할 모듈 정보 객체가 담긴 배열을 설정할 수 있어야 합니다.",
        "infoArray(필수) 파라미터가 Array 가 아니면 모듈이 로드되지 않아야 합니다.",
        "infoArray[i].src(필수) 파라미터로 로드할 JavaScript(XML) 파일의 경로를 설정할 수 있어야 합니다.",
        "infoArray[i].name(필수) 파라미터로 프로젝트 공통 변수에 등록할 이름을 설정할 수 있어야 합니다.",
        "모든 모듈 로드 완료를 나타내는 Promise 객체를 반환해야 합니다.",
        "반환된 Promise 는 await 또는 .then() 으로 로드 완료 후 처리를 할 수 있어야 합니다.",
    ]
}



scwin.COMMON_PATHS = {
    "util" : "/cm/gcc/util.xml",
    "str"  : "/cm/gcc/str.xml",
    "num"  : "/cm/gcc/num.xml"
};

// 테스트 시작 전 특정 이름의 전역 슬롯을 초기화
scwin.resetSlot = function (slotName) {
    try {
        if (window.$c && window.$c[slotName]) {
            delete window.$c[slotName];
        }
    } catch (e) {}
};

// 고정 URL 의 HTTP 요청 수를 반환 (reload 동작 검증용)
scwin.countRequests = function (url) {
    return performance.getEntriesByName(location.origin + url).length;
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// case1 : 배열 + await → $c.util, $c.num 로드 후 메소드 호출 확인
scwin.btn_loadGlobalCommon_await_onclick = async function () {
    scwin.resetSlot("tc_util");
    scwin.resetSlot("tc_num");

    var infoArr = [
        {"src" : scwin.COMMON_PATHS.util, "name" : "tc_util"},
        {"src" : scwin.COMMON_PATHS.num,  "name" : "tc_num"}
    ];
    await $p.loadGlobalCommon(infoArr);

    wf_body_bottom.getObj("scwin").setReturnValue("$c.tc_util.isEmpty($p, '') : " + $c.tc_util.isEmpty($p, ""));
    wf_body_bottom.getObj("scwin").setReturnValue("$c.tc_num.round($p, 3.14159, 2) : " + $c.tc_num.round($p, 3.14159, 2));
}



// case2 : .then() 후속 처리 + Promise 반환 확인
scwin.btn_loadGlobalCommon_then_onclick = function () {
    scwin.resetSlot("tc_str");

    var infoArr = [{"src" : scwin.COMMON_PATHS.str, "name" : "tc_str"}];
    var retVal = $p.loadGlobalCommon(infoArr);

    wf_body_bottom.getObj("scwin").setReturnValue("retVal instanceof Promise : " + (retVal instanceof Promise));

    retVal.then(function () {
        wf_body_bottom.getObj("scwin").setReturnValue(".then() 후 $c.tc_str.trim($p, ' a ') : '" + $c.tc_str.trim($p, " a ") + "'");
    });
}



// case3 : infoArray 가 Array 가 아닌 경우 (String 전달) → 모듈 미로드
scwin.btn_loadGlobalCommon_notArray_onclick = async function () {
    scwin.resetSlot("tc_notArray");

    await $p.loadGlobalCommon("not_an_array");

    wf_body_bottom.getObj("scwin").setReturnValue("infoArray 가 Array 가 아닐 때 window.$c.tc_notArray : " + (typeof window.$c.tc_notArray));
}



// par_case selectbox 값에 따라 각 테스트 케이스 실행
scwin.btn_loadGlobalCommon_run_onclick = function () {
    var caseId = par_case.getValue();
    var handlers = {
        "await"    : scwin.btn_loadGlobalCommon_await_onclick,
        "then"     : scwin.btn_loadGlobalCommon_then_onclick,
        "notArray" : scwin.btn_loadGlobalCommon_notArray_onclick
    };
    var fn = handlers[caseId];
    if (typeof fn === "function") {
        fn();
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("케이스를 선택하세요.");
    }
}
